<?php $e = static fn (mixed $value): string => App\Core\View::e($value); ?>
<section class="portal-page-heading"><p class="eyebrow"><?= $e($championship['name']) ?></p><h1>Fale com a organização</h1><p>Envie sua dúvida, solicitação ou sinalização. Sua mensagem chega ao painel administrativo do campeonato.</p></section>
<section class="portal-contact"><form method="post" action="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/contato')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><?php foreach (($errors ?? []) as $error): ?><p class="alert" role="alert"><?= $e($error) ?></p><?php endforeach; ?><?php if (!empty($message)): ?><p class="success" role="status"><?= $e($message) ?></p><?php endif; ?><div class="contact-grid"><label>Nome completo<input name="name" required maxlength="160" value="<?= $e($values['name'] ?? '') ?>"></label><label>E-mail<input type="email" name="email" required maxlength="190" value="<?= $e($values['email'] ?? '') ?>"></label><label>Telefone<input name="phone" maxlength="40" value="<?= $e($values['phone'] ?? '') ?>"></label><label>Assunto<select name="subject" required><option value="">Selecione</option><?php foreach (['competitions' => 'Competições', 'sponsorship' => 'Patrocínio', 'transfers' => 'Transferências', 'documents' => 'Documentos', 'result_error' => 'Erros em resultados', 'other' => 'Outro'] as $key => $label): ?><option value="<?= $key ?>" <?= ($values['subject'] ?? '') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label></div><label>Mensagem<textarea name="message" rows="7" minlength="10" maxlength="5000" required><?= $e($values['message'] ?? '') ?></textarea></label><button type="submit">Enviar mensagem</button></form></section>
